(() => {
  "use strict";
  const index = window.pagesEvidenceIndex;
  const relocated = new Set(index.paths);

  function evidenceURL(input) {
    let url, path;
    try {
      url = new URL(input, document.baseURI);
      path = decodeURIComponent(url.pathname);
    } catch {
      return null;
    }
    if ((url.origin !== location.origin && url.origin !== "https://" + index.origin) ||
        !path.startsWith(index.prefix)) {
      return null;
    }
    const name = path.slice(index.prefix.length);
    if (!relocated.has(name)) {
      return null;
    }
    const destination = new URL(index.raw + name.split("/").map(encodeURIComponent).join("/"));
    destination.search = url.search;
    destination.hash = url.hash;
    return destination.href;
  }

  const recovery = document.getElementById("pages-evidence-recovery");
  if (recovery) {
    const target = evidenceURL(location.href);
    if (target) {
      const link = recovery.querySelector("a");
      link.href = target;
      recovery.hidden = false;
      location.replace(target);
    }
    return;
  }

  const nativeFetch = window.fetch.bind(window);
  window.fetch = (input, init) => {
    const request = input instanceof Request ? input : null;
    const target = evidenceURL(request?.url ?? input);
    const method = (init?.method ?? request?.method ?? "GET").toUpperCase();
    if (!target || (method !== "GET" && method !== "HEAD")) {
      return nativeFetch(input, init);
    }
    const originalHeaders = new Headers(init?.headers ?? request?.headers);
    const headers = new Headers();
    for (const name of ["Accept", "Range"]) {
      if (originalHeaders.has(name)) {
        headers.set(name, originalHeaders.get(name));
      }
    }
    return nativeFetch(target, { method, headers, mode: "cors", credentials: "omit",
      referrerPolicy: "no-referrer", signal: init?.signal ?? request?.signal });
  };

  function retarget(node) {
    if (!(node instanceof Element)) {
      return;
    }
    if (node.matches("a[href], area[href]")) {
      const target = evidenceURL(node.getAttribute("href"));
      if (target) {
        node.href = target;
      }
    }
    for (const link of node.querySelectorAll("a[href], area[href]")) {
      const target = evidenceURL(link.getAttribute("href"));
      if (target) {
        link.href = target;
      }
    }
  }

  const observer = new MutationObserver(records => {
    for (const record of records) {
      if (record.type === "attributes") {
        const link = record.target;
        if (link.matches("a[href], area[href]")) {
          const target = evidenceURL(link.getAttribute("href"));
          if (target) {
            link.href = target;
          }
        }
      } else {
        for (const node of record.addedNodes) {
          retarget(node);
        }
      }
    }
  });
  observer.observe(document.documentElement, { childList: true, subtree: true, attributes: true,
    attributeFilter: ["href"] });
})();
